data_contract.model:
id; subject string(255) req; requested_at date req; priority enum req;
requester_id FK users req; function_manager_id FK users req; customer_id FK registries null;
supplier_id FK registries null; work_order_id FK work_orders null; company_id FK companies req;
company_site_id FK company_sites req; operational_site_id FK operational_sites req;
business_function_id FK business_functions req; created_by FK users (non fillable);
notes text null; delivery_terms text null; procurement_plan text null;
technical_requirements text null; special_conditions text null;
taxable_total, vat_total, grand_total decimal(14,2) default 0 (non fillable);
status enum open|closed default open; closed_by FK users null; closed_at datetime null;
close_reason text null; timestamps.

id; purchase_request_id FK cascade; position unsigned int; product_id FK products null;
description string(500) req; reason text null; unit_of_measure_id FK null;
quantity decimal(12,3) req; unit_price decimal(14,2) req; vat_rate_id FK vat_rates null;
taxable_amount, vat_amount, total_amount decimal(14,2); status enum default pending_approval;
approved_by FK users null; approved_at datetime null; oda_reference string(50) null (D-3);
timestamps.
